fixtures.raw:
{
  "options": [
    {
      "widgetType": "excerpt",
      "config": {
        "article": "Marie Curie",
        "project": "en.wikipedia"
      },
      "reason": "Displays the lead paragraph, short description, and image of the Marie Curie article."
    },
    {
      "widgetType": "speaker",
      "config": {
        "text": "{{widget:excerpt}}",
        "lang": "en",
        "speakOnChange": true
      },
      "reason": "Reads the text output from the Excerpt widget aloud; connect it to the Excerpt widget in the board settings."
    }
  ]
}

{
  "options": [
    {
      "widgetType": "articleList",
      "config": {
        "articles": "Article 1\nArticle 2",
        "project": "en.wikipedia",
        "enrich": true
      },
      "reason": "Article List displays a clickable list of articles with thumbnails and intros; update the 'Article titles' field in this widget's config to change the list."
    },
    {
      "widgetType": "listSource",
      "config": {
        "title": "My Favorites",
        "items": "Article 1\nArticle 2"
      },
      "reason": "Text List acts as a single source of truth for your article titles; you can then wire other widgets to it via {{widget:<id>}} so they update automatically when you edit this list."
    }
  ]
}

{
  "options": [
    {
      "widgetType": "excerpt",
      "config": {
        "article": "Main_Page",
        "project": "en.wikipedia"
      },
      "reason": "Fetches the article summary; wire the Translate widget's text field to this widget's output using {{widget:<excerpt_id>}}."
    },
    {
      "widgetType": "translate",
      "config": {
        "text": "{{widget:excerpt}}",
        "from": "en",
        "to": "fr",
        "display": "translation"
      },
      "reason": "Translates the summary to French; wire the Speaker widget's source to this widget's 'speech' channel for correct voice selection."
    },
    {
      "widgetType": "speaker",
      "config": {
        "source": "translate#speech",
        "lang": "fr",
        "speakOnChange": true
      },
      "reason": "Speaks the French translation aloud; set the source to the Translate widget's speech channel to auto-detect language and voice."
    }
  ]
}

{
  "options": [
    {
      "widgetType": "boardControls",
      "config": {
        "title": "Institution Selector",
        "spec": "category | buttons | Collection | Images from the Metropolitan Museum of Art, Images from the Library of Congress"
      },
      "reason": "This controller creates a button menu to switch the board parameter {{category}} between the two institutions, driving the other widgets."
    },
    {
      "widgetType": "glamorgan",
      "config": {
        "category": "{{category}}",
        "depth": 1,
        "year": 2026,
        "month": 1,
        "fileBudget": 500,
        "topN": 5,
        "showDetail": true
      },
      "reason": "GLAM Category Usage provides detailed impact stats (files, used files, pages, views) for the selected Commons category."
    },
    {
      "widgetType": "categorySize",
      "config": {
        "category": "{{category}}",
        "wiki": "commons.wikimedia",
        "sampleCount": 6
      },
      "reason": "Category Size shows the total file/page count and a random sample of images from the selected collection."
    }
  ]
}
